function init() {
  document.getElementById('footer-year').textContent = new Date().getFullYear();

  // Restore theme
  const savedTheme = localStorage.getItem('rub_theme');
  if (savedTheme) document.body.className = savedTheme;

  initRadio();
  renderHome();
}


